<?php
require_once __DIR__.'/lib.php';
$users=load_json('users.json',[]);$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
  check_csrf();$action=$_POST['action']??'';
  if($action==='setup' && count($users)===0){$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$pass=$_POST['password']??'';if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<10){$error='Enter a name, valid email and password of at least 10 characters.';}else{$users[]=['id'=>bin2hex(random_bytes(8)),'name'=>$name,'email'=>$email,'hash'=>password_hash($pass,PASSWORD_DEFAULT),'role'=>'owner'];save_json('users.json',$users);$_SESSION['user']=['id'=>$users[0]['id'],'name'=>$name,'email'=>$email,'role'=>'owner'];redirect('dashboard.php');}}
  elseif($action==='login'){$email=strtolower(trim($_POST['email']??''));$pass=$_POST['password']??'';$found=null;foreach($users as $u){if(strtolower($u['email'])===$email && password_verify($pass,$u['hash'])){$found=$u;break;}}if($found){session_regenerate_id(true);$_SESSION['user']=['id'=>$found['id'],'name'=>$found['name'],'email'=>$found['email'],'role'=>$found['role']??'admin'];redirect('dashboard.php');}else{$error='Email or password was not recognised.';}}
}
if(current_user())redirect('dashboard.php');$setup=count($users)===0;
